def Stationary_check(dataframe):
    check = adfuller(dataframe.dropna())
    print(f"ADF Statistic: {check[0]}")
    print(f"p-value: {check[1]}")
    print("Critical Values:")
    for key, value in check[4].items():
        print('\t%s: %.3f' % (key, value))
    if check[0] &gt; check[4]["1%"]:
        print("Time Series is Non-Stationary")
    else:
        print("Time Series is Stationary")
 

# examining the series' stationary state

List_df_ND = [ dataframe_N1["Diff"], dataframe_N2["Diff"], dataframe_N3["Diff"], dataframe_N4["Diff"]]
print("Checking the transformed series for stationarity:")
for i in List_df_ND:
    print("\n")
    Stationary_check(i)
</textarea></div><p><strong>Output:</strong></p><img alt="Traffic Prediction Using Machine Learning" src="https://images.tpointtech.com/tutorial/machine-learning/images/traffic-prediction-using-machine-learning14.png"/><h2 class="h2">Preparing the data for the neural network :</h2><ul class="points"><li>Splitting the test train sets</li><li>Assigning X as features and y as target</li><li>Reshaping data for neural net</li></ul><div class="codeblock"><textarea class="java" name="code"># Several NA values were produced as a result of differencing using a week's worth of data.
dataframe_J1 = dataframe_N1["Diff"].dropna()
